import{_ as o,l as n,o as e,c as i,v as l,p as s,x as r,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"推理 RL 闭环","description":"","frontmatter":{"title":"推理 RL 闭环","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reasoning-rl-loop.md","filePath":"llm/reasoning-rl-loop.md","lastUpdated":1789023840000}'),d={name:"llm/reasoning-rl-loop.md"};function c(A,a,R,T,m,S){const t=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=l('<h1 id="推理-rl-闭环" tabindex="-1">推理 RL 闭环 <a class="header-anchor" href="#推理-rl-闭环" aria-label="Permalink to &quot;推理 RL 闭环&quot;">​</a></h1><div class="epigraph"><p>冷启动模仿长链，校验器给对错，预算管长度，拒绝采样再把新的对链写回监督——几段不是并列菜单，而是同一条环上的相位。</p><footer>—— 归纳 DeepSeek-R1 一类「监督冷启动 → 可验证 RL → 再对齐」的流程，而不是某一家的超参表</footer></div><p>前面三课分别给了 <a href="/llm/long-cot-sft">Long CoT SFT</a>、<a href="/llm/verifiable-reward">可验证奖励</a>、<a href="/llm/length-budget-rl">长度预算</a>。本课把它们收成 <strong>闭环</strong>：输出会成为下一轮的教师数据，路由与超参随相位切换，而不是训完 SFT 就停或无限 RL 到崩溃。缺口是相位之间的接口——何时停止 RL、哪些轨迹可以进下一轮 SFT、如何避免对校验器过拟合之后把错误格式锁死。后课 PRM 进环是在这条环上再插一个过程信号，不是另起炉灶。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只做 SFT：策略停在教师邻域，新题型的探索不足。只做 RL：格式、停写、可读性没有先验，稀疏 0/1 学得很慢，还可能毁掉聊天能力。只做长度惩罚：在还不会算的时候压缩，变成短猜。闭环的主张是分相位，每相位一个主目标：</p><ol><li><strong>冷启动 SFT</strong>：格式、切步、抽取、中等长度。</li><li><strong>可验证 RL</strong>：在预算内最大化 \\(R\\)，允许变丑。</li><li><strong>拒绝采样 / 再 SFT</strong>：把 RL 之后 \\(R=1\\) 且长度合格的轨迹当新教师，蒸馏回更稳的 CE，顺带混入通用指令以防遗忘。</li><li><strong>可选的偏好对齐</strong>：只对开放域，不要覆盖校验器。</li></ol><p>问题是相位切换的判据。看准确率平台、看长度是否仍在爬、看 skip / NaN 率、看通用基准是否掉点。没有判据的「交替」会变成随机复读整条流水线。</p><h3 id="环上的数据流向哪" tabindex="-1">环上的数据流向哪 <a class="header-anchor" href="#环上的数据流向哪" aria-label="Permalink to &quot;环上的数据流向哪&quot;">​</a></h3><p>RL 新采的对链若直接覆盖全部 SFT 数据，分布变窄，风格崩。应 <strong>混合</strong>：保留一批人类 / 教师种子，加上按题分层的 RL 成功轨迹，控制新数据占比。校验器黑客轨迹（过测但过程胡写）一旦进蒸馏，会被 CE 锁死，比 RL 噪声更难洗。<span class="marginnote">闭环不是自动机器学习。拒绝采样的阈值、是否允许同一题多条对链、是否按难度升采样，都是数据工程。R1 报告里的「冷启动 / RL / 再对齐」是相位名；你的题库与校验器决定每个相位该停在哪。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="最小闭环与守门指标" tabindex="-1">最小闭环与守门指标 <a class="header-anchor" href="#最小闭环与守门指标" aria-label="Permalink to &quot;最小闭环与守门指标&quot;">​</a></h3><p>最小闭环实现：固定校验器版本与抽取器。相位 1 用种子长链 SFT。相位 2 用群体 RL，带长度项，连续 \\(k\\) 次评估无提升则停。相位 3 从相位 2 检查点对训练题（及同分布新题）采样，过滤 \\(R=1\\)、\\(\\ell\\lt L\\)、格式合法，与通用指令混合再 SFT。可再进相位 2&#39;，学习率更小。评测集永不进拒绝采样池。</p><p>检查点选择用 <strong>固定预算下的准确率</strong>，不用无预算准确率。否则闭环会选出最能买计算的模型。通用能力用一个小的非推理集守门，掉点超过阈值则在下一轮 SFT 加大混合比。</p>',13)),(e(),s(h,null,{default:r(()=>[p(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%A7%8D%E5%AD%90%E9%95%BF%E9%93%BE%20SFT%22%5D%20--%3E%20RL%5B%22%E5%8F%AF%E9%AA%8C%E8%AF%81%20RL%20%E5%8A%A0%E9%95%BF%E5%BA%A6%E9%A2%84%E7%AE%97%22%5D%0A%20%20RL%20--%3E%20FILT%5B%22%E6%8B%92%E7%BB%9D%E9%87%87%E6%A0%B7%EF%BC%9A%E5%AF%B9%E3%80%81%E7%9F%AD%E3%80%81%E5%8F%AF%E8%A7%A3%E6%9E%90%22%5D%0A%20%20FILT%20--%3E%20MIX%5B%22%E4%B8%8E%E9%80%9A%E7%94%A8%E6%8C%87%E4%BB%A4%E6%B7%B7%E5%90%88%22%5D%0A%20%20MIX%20--%3E%20S2%5B%22%E5%86%8D%20SFT%22%5D%0A%20%20S2%20--%3E%20RL%0A%20%20RL%20--%3E%20GATE%5B%22%E9%A2%84%E7%AE%97%E5%86%85%E5%87%86%E7%A1%AE%E7%8E%87%E4%B8%8E%E9%81%97%E5%BF%98%E5%AE%88%E9%97%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CE 蒸馏有降方差作用：RL 策略的高熵采样被压回一条或几条高回报链，服务更稳、长度更可预期，但探索暂时关闭。所以再 SFT 之后通常需要再开一轮轻量 RL，否则模型在新题上又只会复述蒸馏模板。环的「心跳」是 <strong>探索（RL）与收敛（SFT）交替</strong>。只 SFT 或只 RL 都停在半拍。</p><p>遗忘来自相位 2 的分布偏移：推理题占满梯度，聊天与工具格式被冲掉。混合比是针对这个机制，不是美学。工具调用若要保留，相位 3 必须含 schema 样本，否则闭环会把产品从助手变成竞赛机。</p><p><span class="marginnote">学习率与 batch 在两相位不可共用一套 <a href="/llm/batch-vs-lr">B–η 规则</a>。RL 的有效 batch 是轨迹数，噪声来自 \\(R\\)；SFT 的 batch 是 token。从 RL 切回 SFT 时若沿用 RL 的大 η，会把刚学到的校验器行为冲掉。</span></p><h3 id="何时不要闭环" tabindex="-1">何时不要闭环 <a class="header-anchor" href="#何时不要闭环" aria-label="Permalink to &quot;何时不要闭环&quot;">​</a></h3><p>校验器弱、题量极小、或评测与训练同题，闭环会迅速背答案。此时应停在 SFT + 测试时搜索，或先扩题、加强隐藏测例。开放域为主的产品，可验证闭环只能当子模块，不能当唯一训练。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>墙钟上 RL 采样最贵，再 SFT 次之。工程优化应优先：校验器并行、轨迹截断、对已满窗口的早期 abort。不要先上 PRM 再把闭环跑通——过程模型是下一课的增益，不是本课的前置。</p><p>版本管理：每个相位的校验器、抽取器、预算 \\(L\\)、题库哈希要进检查点元数据。否则三个月后无法解释「为什么第二轮 SFT 掉点」。这与评测种子课将强调的可复现是同一纪律。</p><p><span class="marginnote">不要把某篇技术报告的层数、群体大小、是否先训奖励模型当成闭环定义。本课定义的是数据与目标的相位，以及守门指标。超参表属于你的实验日志。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>闭环 = 长链 SFT → 可验证 RL（含预算）→ 过滤后蒸馏 → 再探索，带守门。</li><li>切换看固定预算准确率与遗忘，不看无约束分数。</li><li>拒绝采样必须挡校验器黑客，并与种子数据混合。</li><li>RL 与 SFT 的 batch / η 机制不同，切换时重标定。</li><li>校验器弱则不要闭环，以免背题。</li><li>出处：DeepSeek-R1 类流程的相位划分；s1 说明轻量 SFT 也可作冷启动。</li></ul>',12))])}const _=o(d,[["render",c]]);export{F as __pageData,_ as default};
